4	use codex_protocol::protocol::RolloutItem;
5	use codex_protocol::protocol::SessionMetaLine;
6	use codex_protocol::protocol::TurnContextItem;
7	use codex_protocol::protocol::USER_MESSAGE_BEGIN;
8	use codex_protocol::protocol::UserMessageEvent;
9	use serde::Serialize;
10	use serde_json::Value;
11	
12	const IMAGE_ONLY_USER_MESSAGE_PLACEHOLDER: &str = "[Image]";
13	
14	/// Apply a rollout item to the metadata structure.
15	pub fn apply_rollout_item(
16	    metadata: &mut ThreadMetadata,
17	    item: &RolloutItem,
18	    default_provider: &str,
19	) {
20	    match item {
21	        RolloutItem::SessionMeta(meta_line) => apply_session_meta_from_item(metadata, meta_line),
22	        RolloutItem::TurnContext(turn_ctx) => apply_turn_context(metadata, turn_ctx),
23	        RolloutItem::EventMsg(event) => apply_event_msg(metadata, event),
24	        RolloutItem::ResponseItem(item) => apply_response_item(metadata, item),
25	        RolloutItem::Compacted(_) => {}
26	    }
27	    if metadata.model_provider.is_empty() {
28	        metadata.model_provider = default_provider.to_string();
29	    }
30	}
31	
32	/// Return whether this rollout item can mutate thread metadata stored in SQLite.
33	pub fn rollout_item_affects_thread_metadata(item: &RolloutItem) -> bool {
34	    match item {
35	        RolloutItem::SessionMeta(_) | RolloutItem::TurnContext(_) => true,
36	        RolloutItem::EventMsg(EventMsg::TokenCount(_) | EventMsg::UserMessage(_)) => true,
37	        RolloutItem::EventMsg(_) | RolloutItem::ResponseItem(_) | RolloutItem::Compacted(_) => {
38	            false
39	        }
40	    }
41	}
42	
43	fn apply_session_meta_from_item(metadata: &mut ThreadMetadata, meta_line: &SessionMetaLine) {
44	    if metadata.id != meta_line.meta.id {
45	        // Ignore session_meta lines that don't match the canonical thread ID,
46	        // e.g., forked rollouts that embed the source session metadata.
47	        return;
48	    }
49	    metadata.id = meta_line.meta.id;
50	    metadata.source = enum_to_string(&meta_line.meta.source);
51	    metadata.thread_source = meta_line.meta.thread_source;
52	    metadata.agent_nickname = meta_line.meta.agent_nickname.clone();
53	    metadata.agent_role = meta_line.meta.agent_role.clone();
54	    metadata.agent_path = meta_line.meta.agent_path.clone();
55	    if let Some(provider) = meta_line.meta.model_provider.as_deref() {
56	        metadata.model_provider = provider.to_string();
57	    }
58	    if !meta_line.meta.cli_version.is_empty() {
59	        metadata.cli_version = meta_line.meta.cli_version.clone();
60	    }
61	    if !meta_line.meta.cwd.as_os_str().is_empty() {
62	        metadata.cwd = meta_line.meta.cwd.clone();
63	    }
64	    if let Some(git) = meta_line.git.as_ref() {
65	        metadata.git_sha = git.commit_hash.as_ref().map(|sha| sha.0.clone());
66	        metadata.git_branch = git.branch.clone();
67	        metadata.git_origin_url = git.repository_url.clone();
68	    }
69	}
70	
71	fn apply_turn_context(metadata: &mut ThreadMetadata, turn_ctx: &TurnContextItem) {
72	    if metadata.cwd.as_os_str().is_empty() {
73	        metadata.cwd = turn_ctx.cwd.clone();
74	    }
75	    metadata.model = Some(turn_ctx.model.clone());
76	    metadata.reasoning_effort = turn_ctx.effort;
77	    metadata.sandbox_policy = enum_to_string(&turn_ctx.sandbox_policy);
78	    metadata.approval_mode = enum_to_string(&turn_ctx.approval_policy);
79	}
80	
81	fn apply_event_msg(metadata: &mut ThreadMetadata, event: &EventMsg) {
82	    match event {
83	        EventMsg::TokenCount(token_count) => {
84	            if let Some(info) = token_count.info.as_ref() {
85	                metadata.tokens_used = info.total_token_usage.total_tokens.max(0);
86	            }
87	        }
88	        EventMsg::UserMessage(user) => {
89	            if metadata.first_user_message.is_none() {
90	                metadata.first_user_message = user_message_preview(user);
91	            }
92	            if metadata.title.is_empty() {
93	                let title = strip_user_message_prefix(user.message.as_str());
94	                if !title.is_empty() {
95	                    metadata.title = title.to_string();
96	                }
97	            }
98	        }
99	        _ => {}
100	    }
101	}
102	
103	fn apply_response_item(_metadata: &mut ThreadMetadata, _item: &ResponseItem) {}
104	
105	fn strip_user_message_prefix(text: &str) -> &str {
106	    match text.find(USER_MESSAGE_BEGIN) {
107	        Some(idx) => text[idx + USER_MESSAGE_BEGIN.len()..].trim(),
108	        None => text.trim(),
109	    }
110	}
111	
112	fn user_message_preview(user: &UserMessageEvent) -> Option<String> {
113	    let message = strip_user_message_prefix(user.message.as_str());
114	    if !message.is_empty() {
115	        return Some(message.to_string());
116	    }
117	    if user
118	        .images
119	        .as_ref()
120	        .is_some_and(|images| !images.is_empty())
121	        || !user.local_images.is_empty()
122	    {
123	        return Some(IMAGE_ONLY_USER_MESSAGE_PLACEHOLDER.to_string());
124	    }
125	    None
126	}
127	
128	pub(crate) fn enum_to_string<T: Serialize>(value: &T) -> String {
129	    match serde_json::to_value(value) {
130	        Ok(Value::String(s)) => s,
131	        Ok(other) => other.to_string(),
132	        Err(_) => String::new(),
133	    }
134	}
