398	fn write_session_file_with_provider(
399	    root: &Path,
400	    ts_str: &str,
401	    uuid: Uuid,
402	    num_records: usize,
403	    source: Option<SessionSource>,
404	    model_provider: Option<&str>,
405	) -> std::io::Result<(OffsetDateTime, Uuid)> {
406	    let format: &[FormatItem] =
407	        format_description!("[year]-[month]-[day]T[hour]-[minute]-[second]");
408	    let dt = PrimitiveDateTime::parse(ts_str, format)
409	        .unwrap()
410	        .assume_utc();
411	    let dir = root
412	        .join("sessions")
413	        .join(format!("{:04}", dt.year()))
414	        .join(format!("{:02}", u8::from(dt.month())))
415	        .join(format!("{:02}", dt.day()));
416	    fs::create_dir_all(&dir)?;
417	
418	    let filename = format!("rollout-{ts_str}-{uuid}.jsonl");
419	    let file_path = dir.join(filename);
420	    let mut file = File::create(file_path)?;
421	
422	    let mut payload = serde_json::json!({
423	        "id": uuid,
424	        "timestamp": ts_str,
425	        "cwd": ".",
426	        "originator": "test_originator",
427	        "cli_version": "test_version",
428	        "base_instructions": null,
429	    });
430	
431	    if let Some(source) = source {
432	        payload["source"] = serde_json::to_value(source).unwrap();
433	    }
434	    if let Some(provider) = model_provider {
435	        payload["model_provider"] = serde_json::Value::String(provider.to_string());
436	    }
437	
438	    let meta = serde_json::json!({
439	        "timestamp": ts_str,
440	        "type": "session_meta",
441	        "payload": payload,
442	    });
443	    writeln!(file, "{meta}")?;
444	
445	    // Include at least one user message event to satisfy listing filters
446	    let user_event = serde_json::json!({
447	        "timestamp": ts_str,
448	        "type": "event_msg",
449	        "payload": {
450	            "type": "user_message",
451	            "message": "Hello from user",
452	            "kind": "plain"
453	        }
454	    });
455	    writeln!(file, "{user_event}")?;
456	
457	    for i in 0..num_records {
458	        let rec = serde_json::json!({
459	            "record_type": "response",
460	            "index": i
461	        });
462	        writeln!(file, "{rec}")?;
463	    }
464	    let times = FileTimes::new().set_modified(dt.into());
465	    file.set_times(times)?;
466	    Ok((dt, uuid))
467	}
